class Solution {
public:
    long long countSubarrays(std::vector<int>& nums, int minK, int maxK) {
        long long ans = 0;
        int last_bad = -1, last_min = -1, last_max = -1;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] < minK || nums[i] > maxK) last_bad = i;
            if (nums[i] == minK) last_min = i;
            if (nums[i] == maxK) last_max = i;
            ans += std::max(0, std::min(last_min, last_max) - last_bad);
        }
        return ans;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long ans = 0;
        int lastBad = -1, lastMin = -1, lastMax = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] < minK || nums[i] > maxK) lastBad = i;
            if (nums[i] == minK) lastMin = i;
            if (nums[i] == maxK) lastMax = i;
            ans += Math.max(0, Math.min(lastMin, lastMax) - lastBad);
        }
        return ans;
    }
}

var countSubarrays = function(nums, minK, maxK) {
    let ans = 0;
    let lastBad = -1, lastMin = -1, lastMax = -1;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < minK || nums[i] > maxK) lastBad = i;
        if (nums[i] === minK) lastMin = i;
        if (nums[i] === maxK) lastMax = i;
        ans += Math.max(0, Math.min(lastMin, lastMax) - lastBad);
    }
    return ans;
};
